WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT p.segmento, count(*) AS pedidos FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) WHERE p.segmento IS NOT NULL GROUP BY p.segmento ORDER BY p.segmento LIMIT 200
